create table if not exists public.koki_content_media(id uuid primary key default gen_random_uuid(),content_id uuid not null references public.koki_contents(id) on delete cascade,source text not null check(source in ('upload','youtube')),storage_path text,youtube_video_id text,mime_type text,file_size_bytes bigint,thumbnail_path text,display_order integer not null default 0 check(display_order>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((source='upload' and storage_path is not null and youtube_video_id is null) or (source='youtube' and storage_path is null and youtube_video_id ~ '^[A-Za-z0-9_-]{11}$')),check(file_size_bytes is null or file_size_bytes between 1 and 31457280));
create index if not exists koki_content_media_content_order on public.koki_content_media(content_id,display_order); alter table public.koki_content_media enable row level security;
create policy koki_content_media_public_read on public.koki_content_media for select using(exists(select 1 from public.koki_contents c where c.id=content_id and c.statut='publié' and c.publication<=now()));
create policy koki_content_media_admin_write on public.koki_content_media for all using(exists(select 1 from public.koki_admin_members m where m.user_id=auth.uid() and m.enabled and m.role in ('superadmin','editor'))) with check(exists(select 1 from public.koki_admin_members m where m.user_id=auth.uid() and m.enabled and m.role in ('superadmin','editor')));